import{useEffect,useState}from'react';import type{RouteConfig}from'@mercurjs/dashboard-sdk';import{Actions,Button,Card,Empty,Message,Page,PageHeader,Status}from'../../spike/ui';declare const __BACKEND_URL__:string;export const config:RouteConfig={label:'المرتجعات',rank:68};const api=async(p:string,i?:RequestInit)=>{const r=await fetch(`${__BACKEND_URL__}${p}`,{credentials:'include',...i,headers:{...(i?.body?{'content-type':'application/json'}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d};const tone=(s:string):any=>s==='approved'?'success':s==='rejected'?'danger':s==='requested'?'warning':'muted';const label=(s:string)=>s==='requested'?'بانتظار المراجعة':s==='approved'?'مقبول':s==='rejected'?'مرفوض':s||'—';export default function P(){const[x,setX]=useState<any[]>([]),[m,setM]=useState(''),[busy,setBusy]=useState('');const load=()=>api('/vendor/spike/returns').then(d=>setX(d.returns||[]));useEffect(()=>{load().catch(e=>setM(e.message))},[]);const act=async(id:string,a:string)=>{let reason='';if(a==='reject'&&!(reason=prompt('سبب الرفض')||''))return;try{setBusy(id);await api(`/vendor/spike/returns/${id}`,{method:'POST',body:JSON.stringify({action:a,reason})});setM(a==='approve'?'تم قبول المرتجع وإضافة مبلغ العميل للمستحقات':'تم رفض المرتجع');await load()}catch(e:any){setM(e.message)}finally{setBusy('')}};return <Page><PageHeader title="المرتجعات" description="راجع طلبات الإرجاع الخاصة بمنتجات متجرك وحدد النتيجة بعد فحص المنتج."/>{m&&<Message>{m}</Message>}<Card className="spike-table-card">{x.length?<div className="spike-responsive-table"><table className="spike-vendor-table"><thead><tr><th>الطلب</th><th>المنتج</th><th>المبلغ</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{x.map(r=><tr key={r.id}><td>#{r.order_id}</td><td>{r.product_title||r.product_id}</td><td>{r.amount} {r.currency_code}</td><td><Status tone={tone(r.status)}>{label(r.status)}</Status></td><td>{r.status==='requested'?<Actions><Button disabled={busy===r.id} onClick={()=>act(r.id,'approve')}>قبول - رجع سليم</Button><Button tone="danger" disabled={busy===r.id} onClick={()=>act(r.id,'reject')}>رفض</Button></Actions>:<span className="spike-muted-text">تمت المراجعة</span>}</td></tr>)}</tbody></table></div>:<Empty>لا توجد طلبات إرجاع حاليًا.</Empty>}</Card></Page>}
